'use strict';
const Seabiscuit=(()=>{
 const minimumOdds=170,maxQuoteAge=72*3600000;
 function eligibleQuote(o,g,now=Date.now()){
  if(!o||!g||g.done||o.state!=='pre'||o.timeValid!==true)return false;
  const start=Date.parse(o.date),kickoff=Date.parse(g.date),stamp=Date.parse(o.retrievedAt);
  return [start,kickoff,stamp].every(Number.isFinite)&&Math.min(start,kickoff)>now&&stamp<=now&&now-stamp<=maxQuoteAge&&['homeMoneyline','awayMoneyline'].every(k=>Number.isFinite(o[k])&&Math.abs(o[k])>=100);
 }
 function isUpsetPick(r){return Number.isFinite(r.odds)&&r.odds>=100&&r.p>.5&&r.margin>0&&r.o[r.side==='home'?'awayMoneyline':'homeMoneyline']<0;}
 function isSeabiscuit(r){return isUpsetPick(r)&&r.odds>=minimumOdds;}
 function picks(pool){return pool.filter(isUpsetPick).sort((a,b)=>Number(isSeabiscuit(b))-Number(isSeabiscuit(a))||b.p-a.p||b.odds-a.odds);}
 const api={eligibleQuote,isUpsetPick,isSeabiscuit,picks};
 if(typeof module!=='undefined')module.exports=api;
 if(typeof document==='undefined')return api;
 function time(value){return new Date(value).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET';}
 function card(r){const special=isSeabiscuit(r),opp=r.g[r.side==='home'?'away':'home'],q=forecast(r.f);
  return `<article class="sb-card ${special?'sb-special':''}"><div class="sb-card-top"><span class="sb-badge">${special?'<img class="brand-seabiscuit-mark" src="assets/darkhorse-mark-96.webp" alt=""> SEABISCUIT PLAY':'UPSET PICK'}</span><span class="sb-location">${r.g.neutral?'NEUTRAL SITE':r.side==='home'?'HOME UNDERDOG':'ROAD UNDERDOG'}</span></div><div class="sb-logo">${logo(r.team)}</div><h3>${rankedName(r.team)}</h3><button type="button" class="sb-odds gd-price" data-add-game="${esc(r.id)}" data-add-team="${esc(r.team)}" aria-label="Add ${esc(name(r.team))} moneyline +${r.odds}">+${r.odds}</button><div class="sb-market">MONEYLINE · TO WIN OUTRIGHT</div><p class="sb-opponent">${r.g.neutral||r.side==='home'?'vs.':'@'} ${rankedName(opp)}</p><div class="sb-model"><div><small>MODEL WIN CHANCE</small><b>${pPercent(r.p)}</b></div><div><small>PROJECTED SCORE</small><b>${r.side==='home'?q.h:q.a}<span> – </span>${r.side==='home'?q.a:q.h}</b></div></div>${(r.f.coachChangeEvents||[]).map(e=>`<p class="sb-coach-note">${e.team===r.team?'This team’s':'Opponent’s'} first game after a coaching change. See the matchup report.</p>`).join('')}<p class="sb-reason">${esc(pReason(r))}</p><p class="sb-kickoff">${esc(time(r.o.date))}<br>${esc(r.o.channels?.length?r.o.channels.join(' / '):channel(r.g))}</p><button type="button" class="sb-report" data-sb-match="${esc(r.id)}">Why this pick? <span>↗</span></button><div class="sb-source">${esc(r.o.provider||'Posted odds')} · Checked ${esc(time(r.o.retrievedAt))}</div></article>`;
 }
 function section(week,forecasts,pool,now){const selected=picks(pool),special=selected.filter(isSeabiscuit),priced=new Set(pool.map(r=>r.id)).size,upcoming=forecasts.filter(f=>{const g=game(f);return !g.done&&Date.parse(g.date)>now;}).length,stale=DartHealth.health(M,now).stale;
  let status=stale?'New picks are paused while the forecast data refreshes.':!priced?'No eligible moneyline quotes are loaded for this selection yet.':!special.length?'No SEABISCUIT PLAY qualifies in this selection yet.':`${special.length} SEABISCUIT ${special.length===1?'PLAY':'PLAYS'} · Model picks an underdog at +${minimumOdds} or higher to win.`;
  return `<section class="sb-week"><div class="sb-week-head"><div><div class="eyebrow">THE DARKHORSE MODEL · ${esc(pWeekLabel(week))}</div><h2>THE UPSET <span>CARD.</span></h2><p>Underdogs we pick to win. <b>Outright.</b></p></div><span class="sb-count">${selected.length}<small>UPSET PICKS</small></span></div><div class="sb-rule ${special.length?'sb-rule-active':''}"><span class="sb-horse" aria-hidden="true"><img src="assets/darkhorse-mark-96.webp" alt="" width="42" height="42"></span><div><b>SEABISCUIT PLAY</b><p>+${minimumOdds} or higher moneyline. Our model picks the win.</p><small>${esc(status)}</small></div>${special.length?'<span class="sb-live-dot" aria-hidden="true"></span>':''}</div>${selected.length?`<div class="sb-scroll-note"><span>LOGO. ODDS. OUR PICK.</span><span>Scroll for all ${selected.length} picks →</span></div><div class="sb-rail" tabindex="0" role="region" aria-label="${esc(pWeekLabel(week))} outright upset picks">${selected.map(card).join('')}</div>`:`<div class="sb-empty">${stale?'Fresh forecasts will bring this card back.':priced?'No priced underdog is projected to win outright in this selection.':'This week’s upset picks will appear here when eligible odds and forecasts are available.'}</div>`}<p class="sb-coverage">${priced} of ${upcoming} upcoming games eligible for this card. Only underdogs the model picks to win appear here. Odds are saved quotes and can change.</p></section>`;
 }
 function bind(mount){mount.querySelectorAll('[data-sb-match]').forEach(b=>b.onclick=()=>{$('matchConference').value='all';fillGames();show(b.dataset.sbMatch);tab('lab');document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'});});}
 api.renderWeek=(week,pool)=>{const mount=$('weeklyUpsets');if(!mount)return;mount.innerHTML=section(week,M.forecasts.filter(f=>pWeek(game(f).date)===week),pool,Date.now());bind(mount);};
 api.renderHub=fs=>{
  if(typeof parlayOdds==='undefined'||!parlayOdds)return;
  let mount=$('seabiscuitHub');if(!mount){mount=document.createElement('div');mount.id='seabiscuitHub';}
  if($('slate').firstElementChild!==mount)$('slate').prepend(mount);
  const now=Date.now(),weeks=[...new Set(fs.filter(f=>Date.parse(game(f).date)>now).map(f=>pWeek(game(f).date)))].sort();
  mount.innerHTML=weeks.map(w=>{const forecasts=fs.filter(f=>pWeek(game(f).date)===w),ids=new Set(forecasts.map(f=>f.id));return section(w,forecasts,pCandidates(w,now).filter(r=>ids.has(r.id)),now);}).join('');bind(mount);
 };
 return api;
})();

/* Sniper Sauce: observed player production and verified bookmaker snapshots. */
(function(root){
'use strict';
const fresh=(q,now=Date.now())=>Number.isFinite(Date.parse(q.updatedAt)) && now-Date.parse(q.updatedAt)>=0 && now-Date.parse(q.updatedAt)<=6*3600000;
const win=(value,q)=>q.side==='Over'?value>q.line:value<q.line;
function rate(p,q){const values=p.samples.map(s=>s.value*p.matchupFactor);return {wins:values.filter(v=>win(v,q)).length,pushes:values.filter(v=>v===q.line).length,n:values.length};}
function dataStale(data,runId,now=Date.now()){
 const age=now-Date.parse(data.inputRetrievedAt);
 return data.refreshRunId!==runId || !Number.isFinite(age) || age<0 || age>30*3600000;
}
function feedStatus(data,stale=false){
 if(stale)return {title:'Player data needs a refresh',message:'This player snapshot no longer matches a fresh forecast. SGP suggestions will resume after a successful update.'};
 const code=data.providerError?.code;
 if(data.lineStatus==='provider_error'){
  if(code==='OUT_OF_USAGE_CREDITS')return {title:'Prop-feed credits exhausted',message:'The Odds API has run out of usage credits. The site cannot retrieve new player-prop lines until credits renew or are replenished. Player averages and projections still work.'};
  if(['INVALID_KEY','DEACTIVATED_KEY','MISSING_KEY'].includes(code))return {title:'Prop-feed access failed',message:'The Odds API rejected the configured key. The site owner needs to check that API account and its saved key. Player averages and projections still work.'};
  if(code==='EXCEEDED_FREQ_LIMIT')return {title:'Prop feed temporarily rate-limited',message:'The Odds API asked us to slow down. The next scheduled refresh will try again; only unexpired saved quotes can be used.'};
  return {title:'Prop feed could not refresh',message:'The connected provider returned an error. The next scheduled refresh will try again. Each game below shows whether it has usable quotes.'};
 }
 if(data.lineStatus==='connected')return {title:'Prop feed connected',message:'A connection does not mean every game has posted props. Each SGP needs current lines from the same sportsbook and enough shared player history. Quotes expire after six hours.'};
 return {title:'Player-prop feed not connected',message:'Player averages and projections are loaded. The site owner needs to connect The Odds API before sportsbook lines and SGP suggestions are available.'};
}
function assess(g,now=Date.now()){
 const blocked=(code,message)=>({code,message,ticket:null});
 if(!Number.isFinite(Date.parse(g.date))||Date.parse(g.date)<=now)return blocked('started','Kickoff has passed. Pregame SGP suggestions are closed.');
 if(g.reviewRequired)return blocked('review','This matchup needs a lineup review before an SGP can be suggested.');
 const quotes=g.players.flatMap(p=>p.quotes);
 if(!quotes.length)return blocked('no_quotes','No posted player-prop lines are available for this matchup yet. A projection alone cannot build an SGP.');
 if(!quotes.some(q=>fresh(q,now)))return blocked('expired','The saved prop lines have expired. We need quotes updated within the last six hours.');
 const withHistory=g.players.filter(p=>p.samples.length>=6&&p.quotes.some(q=>fresh(q,now)));
 if(new Set(withHistory.map(p=>p.id)).size<2)return blocked('history','We need current lines and at least six recorded games for two different players.');
 const candidates=g.players.flatMap(p=>p.quotes.filter(q=>fresh(q,now)).map(q=>({p,q,r:rate(p,q)}))).filter(x=>x.r.n>=6&&x.r.wins/x.r.n>=.6);
 if(new Set(candidates.map(x=>x.p.id)).size<2)return blocked('threshold','Fewer than two players meet the screen: each leg must have beaten its current line in at least 60% of six or more adjusted past performances. No SGP qualifies right now.');
 let best=null;
 let paired=false;
 for(let i=0;i<candidates.length;i++)for(let j=i+1;j<candidates.length;j++){
  const a=candidates[i],b=candidates[j];
  if(a.p.id===b.p.id||a.p.team!==b.p.team||a.q.bookKey!==b.q.bookKey)continue;
  paired=true;
  const pairs=a.p.samples.flatMap(x=>{const y=b.p.samples.find(y=>y.gameId===x.gameId);return y?[[x.value*a.p.matchupFactor,y.value*b.p.matchupFactor]]:[]});
  if(pairs.length<6)continue;
  const hits=pairs.filter(([x,y])=>win(x,a.q)&&win(y,b.q)).length;
  if(!best||hits/pairs.length>best.hits/best.n)best={legs:[a,b],hits,n:pairs.length};
 }
 if(best)return {code:'ready',message:'A two-leg research slip qualifies. Check player availability and the combined price at your sportsbook.',ticket:best};
 if(!paired)return blocked('pairing','The qualifying legs do not pair at the same sportsbook for two different players on the same team. This builder currently supports teammate pairs only.');
 return blocked('shared_history','The qualifying players have fewer than six shared recorded games. There is not enough joint history to suggest this pair.');
}
